<?php require_once dirname(__DIR__) . '/header.php'; ?><?php require_once __DIR__.'/../header.php';?><main class="page"><section class="hero"><h1>Stopwatch Timer</h1><p class="muted">A simple, accurate stopwatch that runs in your browser.</p></section><div class="layout"><section class="tool"><div class="clock" id="clock">00:00:00.00</div><button class="btn" id="start">Start</button><button class="btn" id="pause">Pause</button><button class="btn" id="reset">Reset</button></section><aside class="tools"><h3>🛠️ All Tools</h3><?php $items=['image-compressor.php'=>'🖼️ Image Compressor','image-resizer.php'=>'📐 Image Resizer','jpg-to-png.php'=>'↩️ JPG to PNG','png-to-jpg.php'=>'↩️ PNG to JPG','word-counter.php'=>'📝 Word Counter','case-converter.php'=>'🔤 Case Converter','qr-generator.php'=>'🔐 QR Code Generator','password-generator.php'=>'🔑 Password Generator','json-formatter.php'=>'{} JSON Formatter','url-encoder.php'=>'🔗 URL Encoder','pdf-to-jpg.php'=>'📄 PDF to JPG','duplicate-line-remover.php'=>'🖌️ Duplicate Line Remover','image-cropper.php'=>'✂️ Image Cropper','image-rotator.php'=>'🔄 Image Rotator','gif-maker.php'=>'🎞️ GIF Maker','gif-to-jpg.php'=>'🖼️ GIF to JPG','jpg-to-webp.php'=>'🖼️ JPG to WebP','png-to-webp.php'=>'🖼️ PNG to WebP','pdf-to-png.php'=>'📄 PDF to PNG','pdf-merger.php'=>'📑 PDF Merger','pdf-splitter.php'=>'📄 PDF Splitter','pdf-compressor.php'=>'📦 PDF Compressor','age-calculator.php'=>'🎂 Age Calculator','percentage-calculator.php'=>'% Percentage Calculator','unit-converter.php'=>'📏 Unit Converter','stopwatch-timer.php'=>'⏱️ Stopwatch Timer'];foreach($items as $f=>$n):?><a class="<?=basename($_SERVER['SCRIPT_NAME'])===$f?'active':''?>" href="/tools/<?=htmlspecialchars($f,ENT_QUOTES,'UTF-8')?>"><?=htmlspecialchars($n)?></a><?php endforeach;?><a href="/tool.php">View All Tools →</a></aside></div></main><?php require_once __DIR__.'/../footer.php';?><script>let running=false,startAt=0,elapsed=0,timer;const clock=document.getElementById('clock');function draw(){let x=elapsed;if(running)x+=performance.now()-startAt;let cs=Math.floor(x/10)%100,s=Math.floor(x/1000)%60,m=Math.floor(x/60000)%60,h=Math.floor(x/3600000);clock.textContent=String(h).padStart(2,'0')+':'+String(m).padStart(2,'0')+':'+String(s).padStart(2,'0')+'.'+String(cs).padStart(2,'0')}document.getElementById('start').onclick=()=>{if(!running){running=true;startAt=performance.now();timer=setInterval(draw,10)}};document.getElementById('pause').onclick=()=>{if(running){elapsed+=performance.now()-startAt;running=false;clearInterval(timer);draw()}};document.getElementById('reset').onclick=()=>{running=false;clearInterval(timer);elapsed=0;draw()};</script></body></html>